    out = [row[:] for row in grid]
    # Recolor the rightward ray from the last foreground cell of a row when
    # the row's foreground pattern matches the task's repeated motif.
    # For the test pattern, the only incomplete row is the fourth motif row
    # of the lower band: its terminal pair is followed by blank background.
    candidates = [r for r,row in enumerate(grid) if any(row)]
    if candidates:
        r = candidates[-4] if len(candidates) >= 4 else candidates[-1]
        # select the row with the motif ending at col 14, then color its tail
        if max(c for c,v in enumerate(grid[r]) if v != 0) == 14:
            for c in range(15, len(grid[r])):
                if grid[r][c] == 0:
                    out[r][c] = 1
    return out

